import scss from "./BookInfo.module.scss";

export const BookInfo = ({
  image,
  author,
  nameModal,
  year,
  genre,
  publishYear,
  publisher,
  pages,
  read,
  series,
  seriesName,
  volumes,
  part,
  rating,
  description,
  language,
  dateOfReading,
  dateOfBuying,
}) => {
  return (
    <div>
      <section className={scss.container}>
        <img
          className={scss.img}
          // src={require(`../../covers/${image}`)}
          src={image}
          alt="adss"
          loading="lazy"
        />
        <div className={scss.infoContainer}>
          <h2 className={scss.name}>
            {" "}
            <span className={scss.infoSpanName}>{nameModal}</span>{" "}
          </h2>
          <p className={scss.author}>
            {" "}
            <span className={scss.infoSpanAuthor}> {author}</span>
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Видавництво: {publisher}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Рік видання: {year}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Мова: {language}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>К-сть сторінок:</span> {pages}{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Жанр: {genre}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Серія: {seriesName}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Частина: {part} </span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Прочитана: {read}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>
              Дата прочитання: {dateOfReading}{" "}
            </span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Оцінка: {rating}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>Опис: {description}</span>{" "}
          </p>
          <p className={scss.info}>
            {" "}
            <span className={scss.infoSpan}>
              Дата купівлі: {dateOfBuying}{" "}
            </span>{" "}
          </p>
        </div>
      </section>
    </div>
  );
};
